"""Reader-facing direct literature comparison for section 5.3 of notebook 33.09."""


def result_sections(md, code):
    md(r'''### 5.3. Прямой расчёт с литературными сопротивлениями

Расширение области обратного поиска не дало устойчивого физиологически обоснованного решения. Поэтому следующая проверка задаёт сопротивления независимо от экспериментальных импедансов и сопоставляет прямой прогноз с измерениями каждой сборки. Одновременно проверяется, объясняет ли обнаруженное расхождение упрощение формы лёгкого: расчёт выполняется для модели 4 и для исходной КТ-маски в одном и том же теле, на одной сетке и с одинаковыми контактами.

Для этой проверки использованы частотно определённые значения из [IT’IS, версия 5.0](https://itis.swiss/virtual-population/tissue-properties/downloads/database-v5-0), рассчитанные по [дисперсионным зависимостям Gabriel](https://itis.swiss/virtual-population/tissue-properties/database/dielectric-properties). Сохранённая исходная таблица и ранее извлечённые значения сверены по контрольным суммам; проводимости повторно вычислены при **50 кГц**. Эта частота является принятым литературным ориентиром данной ветки; проверка частоты экспериментального прибора здесь не выполнялась. Применён резистивный вариант модели: ρ = 1/σ, где σ — действительная проводимость в См/м. Диэлектрическая составляющая комплексной проводимости в FEM не включена; равенство такого расчёта полной комплексной задаче отдельно не проверено.

**Заданные параметры:** для всего внелёгочного фона принято сопротивление мышцы **ρ₁ = 2,8423 Ом·м**. Для лёгкого рассчитаны два табличных состояния: **inflated — ρ₂ = 9,7413 Ом·м** и **deflated — ρ₂ = 3,8173 Ом·м**. В первом случае лёгкое в источнике обозначено как расправленное, во втором — как спавшееся. Присвоение свойств мышцы всему фону, включая жировую ткань и кости, является допущением о двухтканном составе. Оно не задаёт измеренного эффективного сопротивления грудной стенки этого человека.

Измерения на вдохе сопоставлены с первым состоянием; измерения на выдохе — со вторым, **только как условная проверка**. Категория deflated не установлена как эквивалент выдоха добровольца. Её значение ниже прежней области поиска для расправленного лёгкого, поскольку относится к другой категории источника. Оно не расширяет автоматически физиологические границы обратной задачи. В обоих состояниях сохраняются исходная геометрия КТ на вдохе, карта h и положение C01. В каждом решении присутствуют четыре конечных контакта диаметром 5 мм; контактные условия те же, что в разделе 1. Неизменность ρ₁ при переходе между состояниями также является условием этого теста.

Выполнены **36 новых прямых решений FEM/CEM**: два тканевых состояния × две формы лёгкого × девять сборок. Интерполяционная библиотека и оптимизация сопротивлений для получения этих импедансов не использовались. Величина Z вычислялась как разность потенциалов измерительных электродов, делённая на заданный ток. Нормировка тока 1 А служит вычислению передаточного сопротивления линейной модели и не описывает ток реального прибора. Экспериментальные уровни взяты из той же таблицы наблюдений, что и выше; дополнительный масштабный коэффициент не вводился. Сопоставимость последовательно записанных размеров сохраняется как ранее принятое условие.

**Таблица 4б. Импедансы исходной двухтканной КТ-модели при заданных литературных сопротивлениях и экспериментальные уровни, Ом.** Выдох сопоставлен с условным сценарием deflated. Полные результаты обеих геометрий сохранены в [расчётной таблице](../MATLAB_TRKG4_real_subjects/output/exploratory/lateral_literature_forward_20260916/comparison.csv); [команды повторения](../MATLAB_TRKG4_real_subjects/output/exploratory/lateral_literature_forward_20260916/README.md) приведены отдельно.''')
    code('''sys.path.insert(0,str(pipe/'tools'))
from lateral_literature_forward import validate as validate_forward, figure as forward_figure
forward_out=pipe/'output/exploratory/lateral_literature_forward_20260916'
forward_plan,forward_responses,forward_observations=validate_forward(forward_out)
forward_qc=json.loads((forward_out/'qc.json').read_text(encoding='utf-8'))
assert forward_qc['analysis_script_sha256']==sha(pipe/'tools/lateral_literature_forward.py')
for name,digest in {**forward_qc['source_sha256'],**forward_qc['output_sha256']}.items():
 assert sha(forward_out/name)==digest
forward_data=pd.read_csv(forward_out/'comparison.csv')
forward_metrics=pd.read_csv(forward_out/'metrics.csv')
forward_table=forward_observations.copy().rename(columns={'L_mm':'L, мм','Z_inhale_hold_ohm':'Вдох: эксперимент','Z_exhale_hold_ohm':'Выдох: эксперимент'})
for state,label in [('inhale','Вдох: КТ'),('exhale','Выдох: КТ, условно')]:
 values=forward_data[(forward_data.state==state)&(forward_data.model=='reference')].set_index('L_mm').Z
 forward_table[label]=forward_table['L, мм'].map(values)
table(forward_table[['L, мм','Вдох: эксперимент','Вдох: КТ','Выдох: эксперимент','Выдох: КТ, условно']])
display(HTML(forward_figure(forward_out).to_html(full_html=False,include_plotlyjs='inline',config={'displaylogo':False,'responsive':True})))
''')
    md(r'''**Рисунок 5. Прямой прогноз импеданса для девяти размеров сборки без подгонки сопротивлений.** Слева показаны измерения на вдохе и расчёт с табличным расправленным лёгким; справа — измерения на выдохе и условный расчёт с категорией deflated. Красные точки обозначают эксперимент, синие — исходную КТ-маску, бирюзовый пунктир — модель 4. Отрезки соединяют рассчитанные или измеренные размеры и не являются отдельной непрерывной моделью зависимости от L. Совпадение синих и бирюзовых линий означает малое различие двух форм лёгкого именно в этих состояниях; их удалённость от красной линии характеризует расхождение прямого прогноза с экспериментом. Одинаковый масштаб панелей позволяет сравнивать абсолютные уровни. Интервалы неопределённости не показаны, поскольку её величина для этих наблюдений не установлена.''')
    code('''fm=forward_metrics.set_index(['state','model'])
fi=fm.loc[('inhale','reference')]; fe=fm.loc[('exhale','reference')]
assert (forward_data.residual_ohm<0).all()
paragraph(f"**Полученный результат.** В исходной КТ-модели расчёт ниже эксперимента для всех девяти размеров. "
 f"Среднее абсолютное относительное расхождение составляет **{num(fi.mape_pct,1)}% на вдохе** и **{num(fe.mape_pct,1)}% в условном сопоставлении с выдохом**. "
 f"Среднеквадратичные расхождения равны соответственно **{num(fi.rmse_ohm,2)} и {num(fe.rmse_ohm,2)} Ом**. "
 f"Максимальное различие модели 4 и исходной КТ-маски во всех 18 сравнениях составляет только **{num(forward_qc['max_model_geometry_difference_ohm'],4)} Ом**. "
 "Таким образом, в проверенных литературных точках упрощение формы лёгкого не объясняет основную часть расхождения с измерениями.")
paragraph(f"Численный контроль: максимальная относительная невязка системы — {forward_qc['max_system_relative_residual']:.2e}, "
 f"ошибка взаимности — {forward_qc['max_reciprocity_error_ohm']:.2e} Ом. "
 "Эти проверки подтверждают решение заданной дискретной задачи; глобальная сходимость по сетке и физическая достоверность двухтканного состава ими не устанавливаются.")
''')
    md(r'''**Научный вывод.** Подстановка табличного сопротивления мышцы в качестве единого сопротивления всего внелёгочного фона вместе с выбранным табличным сопротивлением лёгкого не воспроизводит абсолютные импедансы этих записей. Проверка не определяет истинные ρ₁ и ρ₂ человека и не исключает все литературно допустимые пары: рассчитаны две заранее выбранные точки. Близость двух геометрических моделей здесь также не доказывает их равенства по чувствительности или по точности обратного восстановления во всём диапазоне.

**Следующий шаг.** Для проверки существования подходящей пары сопротивлений следует отдельно исследовать прямую задачу исходной КТ-модели в обоснованной области параметров и её совместное соответствие всем девяти измерениям. При этом нельзя заранее считать сопротивление мышцы известным эффективным сопротивлением неоднородной грудной стенки. Уже полученные отрицательные результаты требуют проверки этого допущения и остальных условий сопоставления; произвольная перенормировка измерений из данной проверки не следует.''')
